target.css:
:root {
  --panel: #fffdf6;
  --ink: #263a2a;
  --muted: #6c796a;
  --line: #d8dfce;
  --moss: #46683f;
  --moss-dark: #294a32;
  --lime: #dce8a9;
  --peach: #efb98c;
  --cream: #f4f0df;
}

.graft-panel {
  box-sizing: border-box;
  width: 480px;
  padding: 15px;
  color: var(--ink);
  background: var(--panel);
  border: 1px solid var(--line);
  border-top: 5px solid var(--moss-dark);
  border-radius: 14px;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 11px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.15px;
  line-height: 1;
}

.panel-head h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 750;
  letter-spacing: -0.5px;
  line-height: 1;
}

.status {
  padding: 5px 8px;
  color: var(--moss-dark);
  background: var(--lime);
  border: 1px solid var(--moss);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.tree-strip {
  display: flex;
  align-items: center;
  min-height: 48px;
  padding: 7px 10px;
  background: var(--cream);
  border-radius: 8px;
}

.tree-mark {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  margin-right: 9px;
  color: var(--panel);
  background: var(--moss);
  border-radius: 50%;
  font-size: 17px;
  font-weight: 800;
}

.tree-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tree-copy strong {
  font-size: 13px;
  line-height: 1.1;
}

.tree-copy span,
.weather span {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.1;
}

.weather {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  margin-left: auto;
}

.weather strong {
  color: var(--moss-dark);
  font-size: 14px;
  line-height: 1.1;
}

.work-grid {
  display: grid;
  grid-template-columns: 1.18fr 0.82fr;
  gap: 12px;
  margin: 11px 0;
}

.route,
.specs {
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.section-label {
  margin: 0 0 7px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
  line-height: 1;
  text-transform: uppercase;
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.steps li {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
}

.step-num {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  color: var(--muted);
  background: var(--cream);
  border-radius: 5px;
  font-size: 9px;
  font-weight: 800;
}

.steps li.done {
  color: var(--ink);
}

.steps li.done .step-num {
  color: var(--panel);
  background: var(--moss);
}

.steps li.active {
  color: var(--moss-dark);
  font-weight: 800;
}

.steps li.active .step-num {
  color: var(--moss-dark);
  background: var(--peach);
}

.specs dl {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 0;
}

.specs div {
  display: flex;
  justify-content: space-between;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
}

.specs div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.specs dt,
.specs dd {
  margin: 0;
  font-size: 11px;
  line-height: 1;
}

.specs dt {
  color: var(--muted);
}

.specs dd {
  color: var(--ink);
  font-weight: 750;
}

.panel-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.legend {
  display: flex;
  gap: 9px;
  color: var(--muted);
  font-size: 10px;
}

.legend span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.legend i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.legend i.ready {
  background: var(--moss);
}

.legend i.waiting {
  background: var(--peach);
}

.seal-button {
  padding: 7px 10px;
  color: var(--panel);
  background: var(--moss-dark);
  border: 0;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.seal-button span {
  margin-left: 6px;
  color: var(--lime);
  font-size: 14px;
}

